import json

def _is_dict(v):
    return isinstance(v, dict)

def _is_list(v):
    return isinstance(v, list)

def _same(a, b):
    return type(a) is type(b) and a == b

def _fmt(v):
    return json.dumps(v, sort_keys=True)

def _walk(a, b, path, out):
    if _is_dict(a) and _is_dict(b):
        for k in a:
            if k not in b:
                out.append(f"- {path}.{k}: {_fmt(a[k])}")
        for k in b:
            if k not in a:
                out.append(f"+ {path}.{k}: {_fmt(b[k])}")
        for k in a:
            if k in b:
                _walk(a[k], b[k], f"{path}.{k}", out)
        return
    if _is_list(a) and _is_list(b):
        n = min(len(a), len(b))
        for i in range(n):
            _walk(a[i], b[i], f"{path}[{i}]", out)
        for i in range(n, len(a)):
            out.append(f"- {path}[{i}]: {_fmt(a[i])}")
        for i in range(n, len(b)):
            out.append(f"+ {path}[{i}]: {_fmt(b[i])}")
        return
    if _same(a, b):
        return
    out.append(f"~ {path}: {_fmt(a)} -> {_fmt(b)}")

def diff(a, b):
    out = []
    _walk(a, b, "$", out)
    return sorted(out)
```

